import{_ as t,o as r,c as n,a2 as i}from"./chunks/framework.CvydjLy7.js";const p=JSON.parse('{"title":"测试：单元测试、切片测试与 Testcontainers","description":"","frontmatter":{"title":"测试：单元测试、切片测试与 Testcontainers"},"headers":[{"level":2,"title":"本篇小节","slug":"本篇小节","link":"#本篇小节","children":[]}],"relativePath":"ch09/index.md","filePath":"ch09/index.md","lastUpdated":1789497795000}'),a={name:"ch09/index.md"};function o(s,e,c,l,h,g){return r(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="测试-单元测试、切片测试与-testcontainers" tabindex="-1">测试：单元测试、切片测试与 Testcontainers <a class="header-anchor" href="#测试-单元测试、切片测试与-testcontainers" aria-label="Permalink to &quot;测试：单元测试、切片测试与 Testcontainers&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本篇对应官方章节</p><p><a href="https://docs.spring.io/spring-boot/reference/testing/index.html" target="_blank" rel="noreferrer">测试总览</a> · <a href="https://docs.spring.io/spring-boot/reference/testing/spring-applications.html" target="_blank" rel="noreferrer">测试 Spring 应用</a> · <a href="https://docs.spring.io/spring-boot/reference/testing/spring-boot-applications.html" target="_blank" rel="noreferrer">测试 Spring Boot 应用</a> · <a href="https://docs.spring.io/spring-boot/reference/testing/test-modules.html" target="_blank" rel="noreferrer">测试模块</a> · <a href="https://docs.spring.io/spring-boot/reference/testing/test-utilities.html" target="_blank" rel="noreferrer">测试工具</a> · <a href="https://docs.spring.io/spring-boot/reference/testing/testcontainers.html" target="_blank" rel="noreferrer">Testcontainers</a></p></div><p>前面八篇写下了 58 个测试。它们能跑，但一直没讲过为什么有的测试要起 Spring、有的不起，为什么有的连数据库、有的只造假对象——这些选择其实是分层的，选错了不会报错，只会让你花 10 秒等一个本该 10 毫秒跑完的断言。</p><p>这一篇把测试本身当成主题，回答四个问题：</p><ul><li><strong>该在哪一层测</strong>：什么代码用普通单元测试，什么必须起容器</li><li><strong>切片怎么切</strong>：<code>@WebMvcTest</code> / <code>@DataJpaTest</code> 各自装配了什么，以及 Boot 4 把这批注解的包名搬到了哪里</li><li><strong>端到端怎么做</strong>：<code>RestTestClient</code> 替代 <code>TestRestTemplate</code> 的实际用法，以及 <code>TestRestTemplate</code> 到底是被废弃还是被搬走</li><li><strong>真实数据库怎么办</strong>：Testcontainers 从 1.x 升到 2.0 之后的模块与包名变化，以及没有 Docker 的环境怎么收场</li></ul><p>配套工程是 <code>activity-server-testing</code>，它是本篇的独立工程，只保留最小一套分层代码（Controller / Service / Repository / Entity），把篇幅全部留给测试。全篇 31 个用例，覆盖下面的每一层。</p><hr><h2 id="本篇小节" tabindex="-1">本篇小节 <a class="header-anchor" href="#本篇小节" aria-label="Permalink to &quot;本篇小节&quot;">​</a></h2><ul><li><a href="/backend-engineering-course/ch09/01.html">9.1 四层测试：先划线，再动手写</a></li><li><a href="/backend-engineering-course/ch09/02.html">9.2 依赖怎么引：总入口与 4.x 的细粒度测试模块</a></li><li><a href="/backend-engineering-course/ch09/03.html">9.3 第一层：纯单元测试，不启动任何容器</a></li><li><a href="/backend-engineering-course/ch09/04.html">9.4 第二层：Web 切片与一批包名的迁移</a></li><li><a href="/backend-engineering-course/ch09/05.html">9.5 数据访问切片：<code>@DataJpaTest</code></a></li><li><a href="/backend-engineering-course/ch09/06.html">9.6 第三层：整体测试，Mock 环境与真实端口</a></li><li><a href="/backend-engineering-course/ch09/07.html">9.7 HTTP 测试客户端怎么选</a></li><li><a href="/backend-engineering-course/ch09/08.html">9.8 条件装配怎么测：<code>ApplicationContextRunner</code></a></li><li><a href="/backend-engineering-course/ch09/09.html">9.9 第四层：Testcontainers，让测试跑在真实数据库上</a></li><li><a href="/backend-engineering-course/ch09/10.html">9.10 Testcontainers 2.0：一次比 Boot 4 更彻底的模块拆分</a></li><li><a href="/backend-engineering-course/ch09/11.html">9.11 没有 Docker 的环境，怎么收场</a></li><li><a href="/backend-engineering-course/ch09/12.html">9.12 几个顺手就能用上的测试工具</a></li><li><a href="/backend-engineering-course/ch09/13.html">9.13 问题速查</a></li><li><a href="/backend-engineering-course/ch09/14.html">9.14 小结与下一步</a></li></ul>',9)])])}const f=t(a,[["render",o]]);export{p as __pageData,f as default};
